package com.fandazi.feature.delivery;
import com.fandazi.feature.order.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DeliveryService { private final OrderService orders; public DeliveryService(OrderService orders){this.orders=orders;} @Transactional public OrderEntity advance(Long userId,Long orderId,OrderStatus next){var current=orders.get(userId,orderId).getStatus();if(!allowed(current,next)) throw new com.fandazi.feature.DomainException("订单状态不可逆或跳跃");return orders.transition(userId,orderId,current,next);} private boolean allowed(OrderStatus current,OrderStatus next){return (current==OrderStatus.MERCHANT_ACCEPTED&&next==OrderStatus.PREPARING)||(current==OrderStatus.PREPARING&&next==OrderStatus.RIDER_PICKED_UP)||(current==OrderStatus.RIDER_PICKED_UP&&next==OrderStatus.DELIVERING)||(current==OrderStatus.DELIVERING&&next==OrderStatus.DELIVERED);} }
